#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;
public sealed class GridShiftV11PlayerSmoke:MonoBehaviour {
 string[] errors=new string[0];
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Environment.GetCommandLineArgs().Contains("-gridshift11-smoke"))return;var go=new GameObject("GridShiftPlayerSmoke");DontDestroyOnLoad(go);go.AddComponent<GridShiftV11PlayerSmoke>();}
 void Capture(){var source=Camera.main;if(source==null)return;var go=new GameObject("SmokeCapture");var camera=go.AddComponent<Camera>();camera.CopyFrom(source);camera.enabled=false;camera.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);var canvases=FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=new RenderTexture(1920,1080,24);camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=.2f;}Canvas.ForceUpdateCanvases();camera.Render();var prior=RenderTexture.active;RenderTexture.active=target;var picture=new Texture2D(1920,1080,TextureFormat.RGB24,false);picture.ReadPixels(new Rect(0,0,1920,1080),0,0);picture.Apply();File.WriteAllBytes(Path.GetFullPath("Docs/Validacao11/player-saves.png"),picture.EncodeToPNG());RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=RenderMode.ScreenSpaceOverlay;canvases[i].worldCamera=null;canvases[i].planeDistance=distances[i];}target.Release();Destroy(target);Destroy(picture);Destroy(go);}
 void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors=errors.Concat(new[]{message}).ToArray();}
 IEnumerator Start(){Application.runInBackground=true;Application.logMessageReceived+=Log;yield return new WaitForSecondsRealtime(4);GridShiftProfiles.RootOverride=Path.Combine(Application.temporaryCachePath,"GridShift11Smoke-"+Guid.NewGuid().ToString("N"));GridShiftProfiles.Login("validacao@local","temporary",out _);GridShiftSavesUI.Instance.Close();GridShiftProfiles.Create(1,"GridShift Logistics",false,out _);FindFirstObjectByType<GridShiftMainMenu>().StartSlot(null,true);float until=Time.realtimeSinceStartup+90;while(!GridShiftCampaignUI.ModalOpen&&Time.realtimeSinceStartup<until)yield return null;if(GridShiftCampaignUI.ModalOpen){var skip=GridShiftCampaignUI.Instance.GetComponentsInChildren<UnityEngine.UI.Button>().FirstOrDefault(b=>b.name=="Pular introdução / Começar");skip?.onClick.Invoke();}while((DeliveryManager.Instance==null||!DeliveryManager.Instance.GetComponent<DeliveryPersistence>().Ready||WorldSession.Instance==null||WorldSession.Instance.Busy||SceneManager.GetActiveScene().name!="Office")&&Time.realtimeSinceStartup<until)yield return null;bool ready=DeliveryManager.Instance!=null&&SceneManager.GetActiveScene().name=="Office"&&!WorldSession.Instance.Busy;if(ready){DeliveryManager.Instance.GetComponent<DeliveryPersistence>().Save();GridShiftSavesUI.Instance.Open("load");yield return new WaitForSecondsRealtime(2);Capture();yield return new WaitForSecondsRealtime(2);}Directory.CreateDirectory("Docs/Validacao11");File.WriteAllText("Docs/Validacao11/player-smoke.txt","Office ready: "+ready+"\nActive cameras: "+FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(c=>c.enabled)+"\nErrors: "+string.Join("; ",errors)+"\nRESULT "+(ready&&errors.Length==0?"SUCCESS":"FAILURE"));Application.Quit(ready&&errors.Length==0?0:1);}
}
#endif

